#include <cstdio>
#include <mutex>
#include <thread>

std::mutex a, b;
long n = 0;

void forward() {
  for (int i = 0; i < 100000; ++i) {
    std::scoped_lock lk(a, b);
    ++n;
  }
}

void backward() {
  for (int i = 0; i < 100000; ++i) {
    std::scoped_lock lk(b, a);
    ++n;
  }
}

int main() {
  std::thread t1(forward), t2(backward);
  t1.join();
  t2.join();
  std::printf("%ld\n", n);
}

